<template><view class="account-page"><view v-if="loading" class="account-state">正在加载…</view><view v-else-if="loadError" class="account-state"><text>{{loadError}}</text><button class="secondary" @click="load">重试</button></view><template v-else><view class="feedback-card"><view class="feedback-heading"><text>反馈内容</text><text>{{length}}/500</text></view><textarea class="feedback-text" :value="content" :maxlength="-1" :disabled="submitting" placeholder="请描述您遇到的问题～" @input="setContent"/><view class="feedback-images"><view v-for="(image,index) in images" :key="image.assetId" class="feedback-image"><image :src="image.previewUrl" mode="aspectFill" @click="preview(index)"/><button :disabled="busy" :aria-label="`移除图片${index+1}`" @click="remove(index)"><image src="/static/common/icon-close-circle.png" mode="aspectFit"/></button></view><button v-if="images.length<maxImages" class="upload-image" :disabled="busy" @click="chooseImages"><image class="upload-icon" src="/static/common/icon-image.png" mode="aspectFit"/><text>{{uploading?'处理中…':'上传'}}</text></button></view><text v-if="maxImages" class="image-count">{{images.length}}/{{maxImages}}张</text></view><text v-if="error" class="account-error">{{error}}</text><button class="primary submit-feedback" :disabled="busy||!content.trim()" @click="submit">{{submitting?'提交中…':'确认提交'}}</button></template></view></template>
<script setup>
import { ref,computed } from 'vue'
import { onLoad,onUnload } from '@dcloudio/uni-app'
import { config } from '../../config'
import { useAuth } from '../../composables/useAuth'
import { getSupportConfig,uploadProfileImage,submitSupportFeedback } from '../../services/profile'
useAuth()
const isMock=config.useMock,content=ref(''),images=ref([]),maxImages=ref(0),loading=ref(true),loadError=ref(''),error=ref(''),uploading=ref(false),submitting=ref(false)
const length=computed(()=>Array.from(content.value).length),busy=computed(()=>uploading.value||submitting.value)
let epoch=0,attemptKey=''
async function load(){const current=++epoch;loading.value=true;loadError.value='';try{const result=await getSupportConfig();if(current!==epoch)return;const limit=result.feedback?.maxImages;if(!Number.isInteger(limit)||limit<0||limit>9)throw new Error('反馈图片配置暂不可用');maxImages.value=limit}catch(reason){if(current===epoch)loadError.value=reason.message}finally{if(current===epoch)loading.value=false}}
function setContent(event){content.value=Array.from(event.detail.value).slice(0,500).join('');attemptKey=''}
function remove(index){if(busy.value)return;images.value.splice(index,1);attemptKey=''}
function preview(index){uni.previewImage({urls:images.value.map(item=>item.previewUrl),current:index})}
async function chooseImages(){if(busy.value)return;const current=epoch;uploading.value=true;error.value='';try{const selected=await new Promise(resolve=>uni.chooseImage({count:maxImages.value-images.value.length,sourceType:['album'],success:resolve,fail:()=>resolve(null)}));if(!selected||current!==epoch)return;for(let i=0;i<selected.tempFilePaths.length&&images.value.length<maxImages.value;i++){const result=await uploadProfileImage({path:selected.tempFilePaths[i],size:selected.tempFiles[i].size},'feedback');if(current!==epoch)return;images.value.push(result);attemptKey=''}}catch(reason){if(current===epoch)error.value=reason.message||'图片上传失败'}finally{if(current===epoch)uploading.value=false}}
async function submit(){if(busy.value||!content.value.trim())return;const current=epoch;submitting.value=true;error.value='';if(!attemptKey)attemptKey=`feedback-${Date.now()}-${Math.random().toString(36).slice(2)}`;try{const result=await submitSupportFeedback({content:content.value,imageAssetIds:images.value.map(item=>item.assetId),idempotencyKey:attemptKey});if(current!==epoch)return;content.value='';images.value=[];attemptKey='';uni.showModal({title:'提交成功',content:result.mockOnly?'感谢您的反馈。':'感谢您的反馈，我们会尽快处理。',showCancel:false})}catch(reason){if(current===epoch)error.value=reason.message||'提交失败，请重试'}finally{if(current===epoch)submitting.value=false}}
onLoad(load);onUnload(()=>{++epoch})
</script>
<style>@import '../../styles/account.css';</style>
<style scoped>.feedback-card{background:#343a5b;border-radius:24rpx;padding:26rpx 24rpx}.feedback-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:26rpx}.feedback-heading>text:first-child{font-size:30rpx;font-weight:600}.feedback-heading>text:last-child{font-size:24rpx;color:#97a5bf}.feedback-text{width:100%;height:270rpx;color:#e8effc;line-height:1.8;font-size:27rpx}.feedback-images{display:flex;flex-wrap:wrap;gap:20rpx;margin-top:20rpx}.feedback-image,.upload-image{width:146rpx;height:146rpx;border-radius:16rpx;position:relative}.feedback-image>image{width:100%;height:100%;border-radius:16rpx}.feedback-image button{position:absolute;right:-8rpx;top:-8rpx;padding:0;margin:0;background:none;line-height:1}.feedback-image button image{width:40rpx;height:40rpx}.upload-image{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12rpx;background:#464f70;color:#9ba9c4;font-size:24rpx;padding:0;margin:0;line-height:1.6}.upload-icon{height:52rpx;width:52rpx}.image-count{display:block;font-size:21rpx;color:#8e9eb9;margin-top:16rpx}.submit-feedback{margin:40rpx 24rpx 0}</style>
